<script setup>
import { computed, onMounted, reactive, ref } from "vue";
import { loadDraft, saveDraft } from "./lib/profileStore";
import { buildContextPackage, normalizeWhitespace, validationMessage } from "./lib/contextPackage";

const activeStep = ref(1), saved = ref(false), saving = ref(false), pdfStatus = ref(""), pdfError = ref(""), extractingPdf = ref(false), formError = ref("");
const evaluationStatus = ref(""), evaluationRunning = ref(false), match = ref(null), outputLanguage = ref("pt-BR"), additionalInstructions = ref(""), includeCoverLetter = ref(false), generationStatus = ref(""), generating = ref(false), generatedDocuments = ref(null), borderlineConfirmed = ref(false), profileMode = ref(""), selectedPdf = ref(null);
const profile = reactive({ name: "", headline: "", location: "", languages: "", skills: "", experience: "", confirmedEvidence: "", stories: "" });
const job = reactive({ url: "", description: "", normalizedDescription: "" });
const bridgeProvider = ref("fake"), bridgeCli = ref("codex"), bridgeEndpoint = ref(""), bridgeModel = ref(""), bridgeApiKey = ref("");
const steps = [{ id: 1, title: "Perfil", note: "Evidências reais" }, { id: 2, title: "Vaga", note: "Contexto e requisitos" }, { id: 3, title: "Match", note: "Leitura da aderência" }, { id: 4, title: "Gerar", note: "Documentos ATS" }];
const contextPackage = computed(() => buildContextPackage(profile, job));
const matchLabel = computed(() => match.value?.score >= 75 ? "Alta aderência" : match.value?.score >= 55 ? "Aderência parcial" : "Baixa aderência");
const classificationLabel = computed(() => ({ Suitable: "Indicado", Borderline: "Com ressalvas", "Not suitable": "Não indicado" }[match.value?.classification] || ""));
const canGenerate = computed(() => match.value?.classification === "Suitable" || (match.value?.classification === "Borderline" && borderlineConfirmed.value));
const radarPoints = (field) => (match.value?.radar || []).map((item, index) => { const angle = (Math.PI * 2 * index) / match.value.radar.length - Math.PI / 2; const radius = item[field] * 0.78; return `${100 + Math.cos(angle) * radius},${100 + Math.sin(angle) * radius}`; }).join(" ");
const axisPoint = (index) => { const count = match.value?.radar?.length || 1; const angle = (Math.PI * 2 * index) / count - Math.PI / 2; return { x: 100 + Math.cos(angle) * 86, y: 100 + Math.sin(angle) * 86 }; };

async function persist() { saving.value = true; saved.value = false; try { await saveDraft({ profile: JSON.parse(JSON.stringify(profile)), job: JSON.parse(JSON.stringify(job)) }); saved.value = true; } finally { saving.value = false; } }
function providerConfig() { if (bridgeProvider.value === "fake") return { kind: "fake" }; if (bridgeProvider.value === "cli") return { kind: "cli", cli: bridgeCli.value }; return { kind: "byok", endpoint: bridgeEndpoint.value, model: bridgeModel.value, apiKey: bridgeApiKey.value }; }
async function bridge(task, options) { const response = await fetch("http://127.0.0.1:4317/v1/execute", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ task, context: contextPackage.value, provider: providerConfig(), options }) }); const result = await response.json(); if (!response.ok) throw new Error(result.error || "A bridge recusou a solicitação."); return result; }
async function evaluate() { formError.value = validationMessage(profile, job); if (formError.value) return; evaluationRunning.value = true; evaluationStatus.value = "Avaliando apenas o pacote revisado…"; try { const result = await bridge("evaluate"); match.value = result.output; generatedDocuments.value = null; borderlineConfirmed.value = false; evaluationStatus.value = result.simulated ? "Avaliação fake criada localmente. Nenhum provedor recebeu seus dados." : `Avaliação recebida via ${result.provider}. Revise as evidências.`; await persist(); activeStep.value = 3; } catch (error) { evaluationStatus.value = `Não foi possível avaliar: ${error.message}`; } finally { evaluationRunning.value = false; } }
async function generateDocuments() { if (!canGenerate.value) return; generationStatus.value = "Gerando documentos a partir das evidências confirmadas…"; generating.value = true; try { const result = await bridge("generate", { language: outputLanguage.value, additionalInstructions: additionalInstructions.value.trim(), coverLetter: includeCoverLetter.value }); generatedDocuments.value = result.output; generationStatus.value = result.simulated ? "Documentos demonstrativos prontos localmente para revisão e download." : "Documentos prontos para revisão e download."; } catch (error) { generationStatus.value = `Não foi possível gerar os documentos: ${error.message}`; } finally { generating.value = false; } }
function download(doc) { const link = document.createElement("a"); const blob = new Blob([doc.content], { type: "text/plain;charset=utf-8" }); link.href = URL.createObjectURL(blob); link.download = doc.filename; link.click(); URL.revokeObjectURL(link.href); }
async function continueTo(step) { if (step === 3) return evaluate(); formError.value = validationMessage(profile, job); if (step >= 3 && formError.value) return; await persist(); activeStep.value = step; }
async function selectStep(step) { if ((step === 3 || step === 4) && !match.value) return evaluate(); activeStep.value = step; }
async function importPdf(file) { if (!file) return; pdfError.value = ""; pdfStatus.value = ""; extractingPdf.value = true; try { const { extractPdfText } = await import("./lib/pdfText"); const result = await extractPdfText(file); profile.confirmedEvidence = result.text; pdfStatus.value = `${file.name} processado localmente · ${result.pages} página${result.pages === 1 ? "" : "s"}. Revise o texto antes de continuar.`; profileMode.value = "manual"; await persist(); } catch (error) { pdfError.value = error.message; } finally { extractingPdf.value = false; } }
function normalizeJob() { job.normalizedDescription = normalizeWhitespace(job.description); }
onMounted(async () => { const draft = await loadDraft(); if (draft?.profile) { Object.assign(profile, draft.profile); if (!profile.confirmedEvidence && profile.experience) profile.confirmedEvidence = profile.experience; profileMode.value = "manual"; } if (draft?.job) Object.assign(job, draft.job); });
</script>

<template>
  <q-layout class="app-shell"><a class="skip-link" href="#workspace">Pular para o conteúdo</a>
    <q-header class="site-header"><q-toolbar class="header-inner"><div class="logo-mark">T</div><q-toolbar-title class="brand-name">Tailor Match <span>AI</span></q-toolbar-title><q-chip square icon="lock" class="privacy-chip">Dados ficam neste navegador</q-chip></q-toolbar></q-header>
    <q-page-container><q-page id="workspace" class="workspace">
      <header class="intro"><p class="eyebrow">CARREIRA COM EVIDÊNCIA</p><h1>Uma candidatura mais precisa começa pelo que é verdadeiro.</h1><p>Organize sua trajetória, compare-a com uma vaga e revise o contexto antes de qualquer envio.</p></header>
      <div class="app-frame"><nav class="progress-nav" aria-label="Etapas da candidatura"><p class="nav-kicker">SEU FLUXO</p><button v-for="step in steps" :key="step.id" type="button" :class="['step-link', { active: activeStep === step.id, done: activeStep > step.id }]" @click="selectStep(step.id)"><span>0{{ step.id }}</span><span><strong>{{ step.title }}</strong><small>{{ step.note }}</small></span></button><div class="nav-note"><q-icon name="verified_user" aria-hidden="true"/> Seu perfil não vai para um servidor do Tailor Match.</div></nav>
        <main class="task-panel">
          <section v-if="activeStep === 1 && !profileMode" class="task-view intake-start"><p class="eyebrow">ETAPA 01</p><h2>Como você quer começar?</h2><p>Escolha o caminho mais confortável. Você poderá complementar ou corrigir o perfil depois, sem repetir informações.</p><div class="intake-choices" role="radiogroup" aria-label="Método de criação do perfil"><button type="button" class="intake-choice" role="radio" aria-checked="false" @click="profileMode = 'upload'"><q-icon name="upload_file" aria-hidden="true"/><strong>Enviar currículo em PDF</strong><span>Extraímos o texto neste navegador para você revisar.</span><q-icon name="arrow_forward" class="choice-arrow" aria-hidden="true"/></button><button type="button" class="intake-choice" role="radio" aria-checked="false" @click="profileMode = 'manual'"><q-icon name="edit_note" aria-hidden="true"/><strong>Preencher manualmente</strong><span>Conte sua experiência, competências e histórias no seu ritmo.</span><q-icon name="arrow_forward" class="choice-arrow" aria-hidden="true"/></button></div><p class="intake-privacy"><q-icon name="lock" aria-hidden="true"/> Nenhum arquivo ou texto sai deste navegador nesta etapa.</p></section>
          <section v-if="activeStep === 1 && profileMode === 'upload'" class="task-view"><div class="task-heading"><div><p class="eyebrow">ETAPA 01 · PDF</p><h2>Envie seu currículo.</h2><p>Escolha um PDF com texto selecionável. A leitura acontece neste navegador e você poderá revisar tudo depois.</p></div><q-btn flat no-caps color="primary" label="Escolher outro caminho" @click="profileMode = ''"/></div><q-file v-model="selectedPdf" outlined accept="application/pdf,.pdf" label="Selecione seu currículo em PDF" hint="Até 10 MB. Nenhum arquivo é enviado para um servidor." :loading="extractingPdf" @update:model-value="importPdf"><template #prepend><q-icon name="upload_file"/></template></q-file><q-banner v-if="pdfError" rounded class="notice error q-mt-md" role="alert">{{ pdfError }} Tente outro PDF ou preencha manualmente.</q-banner></section>
          <section v-else-if="activeStep === 1 && profileMode === 'manual'" class="task-view"><div class="task-heading"><div><p class="eyebrow">ETAPA 01 · MANUAL</p><h2>Conte sua trajetória.</h2><p>Preencha somente o que você pode comprovar. Você pode voltar e importar um PDF a qualquer momento.</p></div><q-btn flat no-caps color="primary" label="Escolher outro caminho" @click="profileMode = ''"/></div><q-banner v-if="pdfStatus" rounded class="notice success" role="status">{{ pdfStatus }}</q-banner><div class="form-grid"><q-input v-model.trim="profile.name" outlined label="Nome" placeholder="Como quer aparecer no CV"/><q-input v-model.trim="profile.headline" outlined label="Título profissional" placeholder="Ex.: Desenvolvedor Full-stack"/><q-input v-model.trim="profile.location" outlined label="Localização / modelo de trabalho"/><q-input v-model.trim="profile.languages" outlined label="Idiomas"/><q-input v-model.trim="profile.skills" outlined class="span-2" label="Tecnologias e competências comprovadas" hint="Separe com vírgulas."/><q-input v-model="profile.confirmedEvidence" outlined type="textarea" autogrow class="span-2" label="Evidências confirmadas" hint="Descreva experiências, responsabilidades e resultados reais."/><q-input v-model="profile.stories" outlined type="textarea" autogrow class="span-2 context-field" label="Contexto bruto (opcional)" hint="Não será promovido automaticamente a fato no seu CV."/></div><div class="action-row"><span>Etapa 1 de 4</span><q-btn unelevated no-caps color="primary" label="Continuar" icon-right="arrow_forward" @click="continueTo(2)"/></div></section>
          <template v-if="activeStep !== 1">
          <section v-if="activeStep === 1" class="task-view"><div class="task-heading"><div><p class="eyebrow">ETAPA 01</p><h2>Seu perfil, sem exageros.</h2><p>Comece pelas evidências. Histórias e anedotas ficam à parte até você confirmá-las.</p></div><q-btn flat no-caps color="primary" icon="save" :label="saving ? 'Salvando…' : saved ? 'Salvo localmente' : 'Salvar rascunho'" @click="persist"/></div><div class="upload-zone"><q-icon name="upload_file" aria-hidden="true"/><div><strong>Importar currículo em PDF</strong><p>Extraímos somente o texto no seu navegador. PDF com texto selecionável, até 10 MB.</p></div><q-file outlined dense accept="application/pdf,.pdf" label="Selecionar PDF" :loading="extractingPdf" @update:model-value="importPdf"/></div><q-banner v-if="pdfStatus" rounded class="notice success" role="status">{{ pdfStatus }}</q-banner><q-banner v-if="pdfError" rounded class="notice error" role="alert">{{ pdfError }}</q-banner><div class="form-grid"><q-input v-model.trim="profile.name" outlined label="Nome" placeholder="Como quer aparecer no CV"/><q-input v-model.trim="profile.headline" outlined label="Título profissional" placeholder="Ex.: Desenvolvedor Full-stack"/><q-input v-model.trim="profile.location" outlined label="Localização / modelo de trabalho"/><q-input v-model.trim="profile.languages" outlined label="Idiomas"/><q-input v-model.trim="profile.skills" outlined class="span-2" label="Tecnologias e competências comprovadas" hint="Separe com vírgulas."/><q-input v-model="profile.confirmedEvidence" outlined type="textarea" autogrow class="span-2" label="Evidências confirmadas" hint="Revise o texto extraído antes de usar como evidência."/><q-input v-model="profile.stories" outlined type="textarea" autogrow class="span-2 context-field" label="Contexto bruto (opcional)" hint="Não será promovido automaticamente a fato no seu CV."/></div><div class="action-row"><span>Etapa 1 de 4</span><q-btn unelevated no-caps color="primary" label="Continuar" icon-right="arrow_forward" @click="continueTo(2)"/></div></section>
          </template>
          <section v-else-if="activeStep === 2" class="task-view"><div class="task-heading"><div><p class="eyebrow">ETAPA 02</p><h2>A vaga é o seu alvo.</h2><p>Cole a descrição completa. A URL é referência local, mas o texto é a fonte confiável para a avaliação.</p></div><q-btn flat no-caps color="primary" icon="save" label="Salvar rascunho" @click="persist"/></div><div class="form-grid"><q-input v-model.trim="job.url" outlined class="span-2" label="URL da vaga (opcional)" type="url"/><q-input v-model="job.description" outlined type="textarea" autogrow class="span-2 job-description" label="Descrição da vaga" @blur="normalizeJob"/></div><div class="inline-tool"><div><strong>Texto mais legível, mesmo conteúdo.</strong><span>Remove apenas espaços e quebras excessivas.</span></div><q-btn outline no-caps color="primary" icon="cleaning_services" label="Normalizar" @click="normalizeJob"/></div><q-expansion-item group="review" icon="visibility" label="Revisar pacote preparado para avaliação" header-class="disclosure"><div class="disclosure-copy">Esse é o contexto que a integração receberá somente após sua ação explícita.</div><pre class="context-preview">{{ JSON.stringify(contextPackage, null, 2) }}</pre></q-expansion-item><q-expansion-item group="review" icon="hub" label="Configurar bridge local (avançado)" header-class="disclosure"><div class="bridge-content"><q-select v-model="bridgeProvider" outlined emit-value map-options label="Modo de integração" :options="[{ label: 'Fake local (teste sem IA)', value: 'fake' }, { label: 'CLI instalada na máquina', value: 'cli' }, { label: 'API com sua própria chave (BYOK)', value: 'byok' }]"/><q-select v-if="bridgeProvider === 'cli'" v-model="bridgeCli" outlined emit-value map-options class="q-mt-md" label="CLI" :options="[{ label: 'Codex CLI', value: 'codex' }, { label: 'Claude CLI', value: 'claude' }]"/><div v-if="bridgeProvider === 'byok'" class="bridge-fields q-mt-md"><q-input v-model.trim="bridgeEndpoint" outlined label="Endpoint HTTPS"/><q-input v-model.trim="bridgeModel" outlined label="Modelo"/><q-input v-model="bridgeApiKey" outlined type="password" label="Chave de API"/></div></div></q-expansion-item><q-banner v-if="formError" rounded class="notice error" role="alert">{{ formError }}</q-banner><div class="action-row"><q-btn flat no-caps label="Voltar" @click="activeStep = 1"/><span>Etapa 2 de 4</span><q-btn unelevated no-caps color="primary" :loading="evaluationRunning" label="Avaliar compatibilidade" icon-right="arrow_forward" @click="evaluate"/></div></section>
          <section v-else-if="activeStep === 3" class="task-view"><div class="task-heading"><div><p class="eyebrow">ETAPA 03 · AVALIAÇÃO</p><h2>Onde você já se encaixa.</h2><p>A avaliação preserva o que foi confirmado e mantém o que falta como gap.</p></div><q-btn flat no-caps color="primary" icon="refresh" :loading="evaluationRunning" label="Reavaliar" @click="evaluate"/></div><q-banner v-if="evaluationStatus" rounded :class="['notice', match ? 'success' : 'error']" role="status">{{ evaluationStatus }}</q-banner><template v-if="match"><div class="match-hero"><div class="score-block"><p>ADERÊNCIA GERAL</p><strong>{{ match.score }}<small>/100</small></strong><span>{{ matchLabel }}</span></div><div class="match-summary"><q-badge outline color="primary">{{ classificationLabel }}</q-badge><h3>{{ match.classification }}</h3><p>{{ match.summary }}</p><div class="strength-list"><span v-for="strength in match.strengths" :key="strength.title"><q-icon name="check_circle" aria-hidden="true"/>{{ strength.title }}</span></div></div></div><div class="insight-grid"><q-card flat bordered><q-card-section><div class="card-title"><div><p class="eyebrow">MAPA DE COMPETÊNCIAS</p><h3>Você × vaga</h3></div><div class="legend"><span><i class="candidate"/>Você</span><span><i class="role"/>Vaga</span></div></div><svg viewBox="0 0 200 200" role="img" :aria-label="`Radar: aderência geral ${match.score} de 100`"><polygon points="100,14 182,73 151,166 49,166 18,73" class="radar-grid"/><polygon :points="radarPoints('role')" class="role-shape"/><polygon :points="radarPoints('candidate')" class="candidate-shape"/><g v-for="(item, index) in match.radar" :key="item.label"><line x1="100" y1="100" :x2="axisPoint(index).x" :y2="axisPoint(index).y" class="axis"/><text :x="100 + (axisPoint(index).x - 100) * 1.14" :y="100 + (axisPoint(index).y - 100) * 1.14" text-anchor="middle" class="radar-label">{{ item.label }}</text></g></svg><ul class="sr-only"><li v-for="item in match.radar" :key="`${item.label}-summary`">{{ item.label }}: perfil {{ item.candidate }}, vaga {{ item.role }}</li></ul></q-card-section></q-card><q-card flat bordered><q-card-section><p class="eyebrow">PONTOS DE ATENÇÃO</p><h3>O que vale endereçar</h3><div v-for="gap in match.gaps" :key="gap.title" class="gap"><q-icon name="priority_high" aria-hidden="true"/><div><strong>{{ gap.title }}</strong><p>{{ gap.detail }}</p><q-badge outline color="warning">{{ gap.level }}</q-badge></div></div></q-card-section></q-card></div><q-expansion-item icon="fact_check" label="Ver evidências usadas na avaliação" header-class="disclosure"><div class="evidence-list"><div v-for="strength in match.strengths" :key="`${strength.title}-evidence`"><strong>{{ strength.title }}</strong><p>{{ strength.evidence }}</p></div></div></q-expansion-item><q-banner v-if="match.classification === 'Not suitable'" rounded class="notice error" role="alert">A geração está bloqueada: esta avaliação não encontrou aderência suficiente. Revise perfil ou vaga, sem inventar competências.</q-banner><q-checkbox v-if="match.classification === 'Borderline'" v-model="borderlineConfirmed" label="Entendo que há ressalvas e quero gerar documentos somente com as evidências confirmadas." class="confirmation"/><div class="action-row"><q-btn flat no-caps label="Editar vaga" @click="activeStep = 2"/><span>Etapa 3 de 4</span><q-btn unelevated no-caps color="primary" :disable="match.classification === 'Not suitable' || (match.classification === 'Borderline' && !borderlineConfirmed)" label="Preparar geração" icon-right="arrow_forward" @click="activeStep = 4"/></div></template><q-banner v-else rounded class="notice error" role="alert">Ainda não há uma avaliação. Volte à vaga e execute a avaliação com a bridge local.</q-banner></section>
          <section v-else class="task-view"><div class="task-heading"><div><p class="eyebrow">ETAPA 04 · GERAÇÃO</p><h2>Documentos sem invenção.</h2><p>O conteúdo é gerado a partir de evidências confirmadas e exportado em texto simples, selecionável e compatível com ATS.</p></div><q-badge outline color="primary">REVISÃO OBRIGATÓRIA</q-badge></div><q-banner v-if="!canGenerate" rounded class="notice error" role="alert">A geração não está liberada para esta avaliação. Revise o match antes de continuar.</q-banner><template v-else><div class="generation-grid"><q-select v-model="outputLanguage" outlined emit-value map-options label="Idioma de saída" :options="[{ label: 'Português (Brasil)', value: 'pt-BR' }, { label: 'English (US)', value: 'en-US' }]"/><q-checkbox v-model="includeCoverLetter" label="Incluir cover letter"/><q-input v-model.trim="additionalInstructions" outlined type="textarea" autogrow class="span-2" label="Instruções adicionais (opcional)" hint="Ex.: enfatizar liderança. Não pode transformar contexto bruto em fato."/></div><div class="generation-action"><div><strong>Antes de exportar</strong><p>Confira cada afirmação. O CV não substitui sua revisão humana.</p></div><q-btn unelevated no-caps color="primary" icon="auto_awesome" :loading="generating" label="Gerar documentos" @click="generateDocuments"/></div><q-banner v-if="generationStatus" rounded :class="['notice', generatedDocuments ? 'success' : 'error']" role="status">{{ generationStatus }}</q-banner><div v-if="generatedDocuments" class="documents"><article class="document-card"><div class="document-heading"><div><p class="eyebrow">CV ATS</p><h3>{{ generatedDocuments.cv.filename }}</h3></div><q-btn flat no-caps color="primary" icon="download" label="Baixar .txt" @click="download(generatedDocuments.cv)"/></div><pre>{{ generatedDocuments.cv.content }}</pre></article><article v-if="generatedDocuments.coverLetter" class="document-card"><div class="document-heading"><div><p class="eyebrow">COVER LETTER</p><h3>{{ generatedDocuments.coverLetter.filename }}</h3></div><q-btn flat no-caps color="primary" icon="download" label="Baixar .txt" @click="download(generatedDocuments.coverLetter)"/></div><pre>{{ generatedDocuments.coverLetter.content }}</pre></article></div></template><div class="action-row"><q-btn flat no-caps label="Voltar ao match" @click="activeStep = 3"/><span>Etapa 4 de 4</span></div></section>
        </main></div>
    </q-page></q-page-container>
  </q-layout>
</template>

<style>
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;700&family=Space+Grotesk:wght@500;600;700&display=swap');
:root{--ink:#1e1b4b;--muted:#475569;--canvas:#faf5ff;--surface:#fff;--line:#ddd6fe;--primary:#7c3aed;--accent:#0891b2;font-family:'DM Sans',system-ui,sans-serif;color:var(--ink);background:var(--canvas)}*{box-sizing:border-box}body{margin:0;background:var(--canvas)}.app-shell{min-height:100dvh;background:linear-gradient(135deg,#faf5ff,#fff 48%,#f1fbfc)}.skip-link{position:fixed;top:-60px;left:16px;z-index:30;padding:10px;background:#1e1b4b;color:#fff}.skip-link:focus{top:16px}.site-header{background:rgba(250,245,255,.94);color:var(--ink);border-bottom:1px solid var(--line);backdrop-filter:blur(12px)}.header-inner{max-width:1180px;min-height:68px;margin:auto;padding:0 24px}.logo-mark{display:grid;place-items:center;width:32px;height:32px;margin-right:10px;border-radius:8px;background:var(--ink);color:#fff;font-family:'Space Grotesk';font-weight:700}.brand-name,h1,h2,h3,strong{font-family:'Space Grotesk',sans-serif}.brand-name span,.eyebrow{color:var(--primary)}.privacy-chip{border:1px solid #cbd5e1;background:transparent;color:#475569}.workspace{max-width:1180px;margin:auto;padding:72px 24px 96px}.intro{max-width:700px;margin:0 auto 48px;text-align:center}.eyebrow,.nav-kicker{margin:0 0 8px;font-size:11px;font-weight:700;letter-spacing:.12em}.intro h1{margin:0;font-size:clamp(36px,5vw,58px);line-height:1.06;letter-spacing:-.055em;text-wrap:balance}.intro>p:last-child{max-width:60ch;margin:20px auto 0;color:var(--muted);font-size:17px;line-height:1.65}.app-frame{display:grid;grid-template-columns:240px minmax(0,1fr);gap:48px}.progress-nav{position:sticky;top:92px;height:max-content;padding-top:16px}.step-link{display:flex;width:100%;gap:14px;padding:14px 12px;border:0;border-left:2px solid transparent;background:transparent;color:#64748b;text-align:left;cursor:pointer;transition:.2s}.step-link:hover,.step-link.active{background:#f3efff;color:var(--ink)}.step-link.active{border-left-color:var(--primary)}.step-link.done>span:first-child{color:#047857}.step-link>span:first-child{font:700 12px 'Space Grotesk';color:#94a3b8}.step-link strong,.step-link small{display:block}.step-link small{margin-top:3px;font-size:12px}.nav-note{margin:30px 12px 0;padding-top:18px;border-top:1px solid var(--line);color:#64748b;font-size:12px;line-height:1.55}.task-view{padding:40px;border:1px solid var(--line);background:var(--surface);box-shadow:0 18px 42px rgba(76,29,149,.07)}.task-heading{display:flex;justify-content:space-between;gap:20px;margin-bottom:32px}.task-heading h2{margin:0;font-size:30px;letter-spacing:-.04em}.task-heading p:last-child{max-width:62ch;margin:10px 0 0;color:var(--muted);line-height:1.6}.upload-zone{display:grid;grid-template-columns:auto 1fr minmax(220px,.8fr);gap:16px;align-items:center;margin-bottom:24px;padding:20px;border:1px dashed #c4b5fd;background:#f8f7ff}.upload-zone>.q-icon{padding:10px;background:#e9e2ff;color:var(--primary);font-size:22px}.upload-zone p,.inline-tool span{margin:4px 0 0;color:var(--muted);font-size:13px;line-height:1.5}.notice{margin-bottom:18px}.success{background:#ecfdf5;color:#065f46}.error{background:#fff1f2;color:#b91c1c}.form-grid,.bridge-fields,.generation-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.span-2{grid-column:span 2}.context-field .q-field__control{background:#fcfbff}.job-description .q-field__control{min-height:220px}.inline-tool{display:flex;align-items:center;justify-content:space-between;gap:20px;margin:20px 0;padding:16px 0;border-block:1px solid #ede9fe}.inline-tool strong,.inline-tool span{display:block}.disclosure{margin-top:8px;color:var(--ink);font-weight:700}.disclosure-copy,.bridge-content,.evidence-list{padding:8px 16px 18px;color:var(--muted);font-size:13px;line-height:1.6}.context-preview,.document-card pre{max-height:280px;overflow:auto;margin:0 16px 16px;padding:14px;background:#17142e;color:#e9e7ff;white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.55 ui-monospace,monospace}.bridge-fields{grid-template-columns:repeat(3,minmax(0,1fr))}.action-row{display:flex;align-items:center;gap:12px;margin-top:36px;padding-top:20px;border-top:1px solid #ede9fe}.action-row>span{margin-left:auto;color:var(--muted);font-size:13px}.match-hero{display:grid;grid-template-columns:240px 1fr;margin-bottom:20px;border:1px solid var(--line)}.score-block{display:flex;flex-direction:column;justify-content:center;min-height:240px;padding:30px;background:var(--ink);color:#fff}.score-block p{margin:0 0 14px;color:#c4b5fd;font-size:11px;font-weight:700;letter-spacing:.12em}.score-block strong{font-size:68px;line-height:1;letter-spacing:-.08em}.score-block small{font-size:20px}.score-block span{margin-top:16px;color:#bbf7d0;font-size:14px;font-weight:700}.match-summary{padding:30px}.match-summary h3{margin:14px 0 0;font-size:25px}.match-summary>p,.gap p{color:var(--muted);line-height:1.65}.strength-list{display:flex;flex-wrap:wrap;gap:10px 18px;margin-top:24px}.strength-list span{font-size:13px}.strength-list .q-icon{color:#059669}.insight-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:20px}.card-title{display:flex;justify-content:space-between;gap:12px}.legend{display:flex;gap:12px;color:var(--muted);font-size:12px}.legend i{display:inline-block;width:9px;height:9px;margin-right:4px;border-radius:50%}.candidate{background:var(--primary)}.role{background:var(--accent)}svg{display:block;width:100%;max-height:280px;margin-top:10px;overflow:visible}.radar-grid{fill:#faf9ff;stroke:#ddd6fe}.axis{stroke:#ddd6fe}.candidate-shape{fill:rgba(124,58,237,.2);stroke:var(--primary);stroke-width:2}.role-shape{fill:rgba(8,145,178,.15);stroke:var(--accent);stroke-width:2}.radar-label{fill:#475569;font-size:8px}.gap{display:flex;gap:12px;padding:18px 0;border-bottom:1px solid #ede9fe}.gap>.q-icon{height:max-content;margin-top:2px;padding:4px;border-radius:50%;background:#fef3c7;color:#a16207}.gap p{margin:5px 0 9px;font-size:13px}.confirmation{display:block;margin-top:24px;padding:16px;background:#fffbeb}.generation-action{display:flex;align-items:center;justify-content:space-between;gap:20px;margin:24px 0;padding:22px;background:#f3efff;border-left:3px solid var(--primary)}.generation-action p{margin:4px 0 0;color:var(--muted)}.documents{display:grid;gap:18px}.document-card{border:1px solid var(--line);background:#fff}.document-heading{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:18px 18px 0}.document-heading h3{margin:0;font-size:18px}.q-btn{min-height:44px}.q-btn:focus-visible,.step-link:focus-visible{outline:3px solid var(--accent);outline-offset:3px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(prefers-reduced-motion:reduce){*,*:before,*:after{transition:none!important;animation:none!important}}@media(max-width:900px){.workspace{padding:48px 20px 72px}.app-frame{grid-template-columns:1fr;gap:24px}.progress-nav{position:static;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;padding:0}.nav-kicker,.nav-note,.step-link small{display:none}.step-link{min-height:72px;padding:10px;border:1px solid var(--line)}.step-link.active{border:2px solid var(--primary)}.task-view{padding:30px}}@media(max-width:640px){.header-inner{padding:0 16px}.privacy-chip{display:none}.workspace{padding:36px 14px 56px}.intro{text-align:left}.intro h1{font-size:38px}.intro>p:last-child{margin-left:0}.progress-nav{overflow:auto;grid-template-columns:repeat(4,120px)}.task-view{padding:24px 18px}.task-heading{display:block}.task-heading>.q-btn{margin-top:10px}.upload-zone,.form-grid,.bridge-fields,.insight-grid,.generation-grid,.match-hero{grid-template-columns:1fr}.span-2{grid-column:auto}.inline-tool,.generation-action{align-items:flex-start;flex-direction:column}.action-row{flex-wrap:wrap}.action-row>span{order:3;width:100%;margin:0;text-align:center}.score-block{min-height:180px}.match-summary{padding:24px}.card-title,.document-heading{display:block}.legend{margin-top:10px}.document-heading .q-btn{margin-top:10px}}
.intake-start>p:not(.eyebrow){max-width:58ch;margin:0;color:var(--muted);line-height:1.65}.intake-start h2{margin:0 0 10px;font-size:30px;letter-spacing:-.04em}.intake-choices{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:28px}.intake-choice{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:12px;padding:22px;border:1px solid var(--line);background:#fff;color:var(--ink);text-align:left;cursor:pointer;transition:border-color .2s,background .2s,box-shadow .2s}.intake-choice:hover{border-color:var(--primary);background:#faf8ff;box-shadow:0 10px 22px rgba(76,29,149,.09)}.intake-choice>.q-icon:first-child{grid-row:span 2;padding:10px;background:#f0eaff;color:var(--primary);font-size:24px}.intake-choice strong{font-size:17px}.intake-choice span{color:var(--muted);font-size:13px;line-height:1.5}.intake-choice .choice-arrow{color:var(--primary)}.intake-privacy{display:flex;align-items:center;gap:8px;margin:20px 0 0!important;color:var(--muted);font-size:13px}.intake-privacy .q-icon{color:#047857}@media(max-width:640px){.intake-choices{grid-template-columns:1fr}.intake-choice{min-height:112px}}
